    usar(a, b);
}
// se cierra primero b, despues a

class Recurso implements AutoCloseable {
    String nombre;
    Recurso(String nombre) { this.nombre = nombre; }
    public void close() { System.out.println("cerrando " + nombre); }
}

try (Recurso a = new Recurso("A"); Recurso b = new Recurso("B")) {
    System.out.println("usando recursos");
}

